template.script:
document.addEventListener('DOMContentLoaded', function () {
  const stateData = ;
  const userData = ;
  const monthlyData = ;
  const topCustomers = ;

  new Chart(document.getElementById('stateChart'), {
    type: 'pie',
    data: {
      labels: Object.keys(stateData),
      datasets: [{
        data: Object.values(stateData),
        backgroundColor: ['#60a5fa', '#f87171', '#34d399', '#fbbf24', '#c084fc']
      }]
    },
    options: { responsive: true }
  });

  new Chart(document.getElementById('userChart'), {
    type: 'bar',
    data: {
      labels: Object.keys(userData),
      datasets: [{
        label: 'Total Sales',
        data: Object.values(userData),
        backgroundColor: '#4ade80'
      }]
    },
    options: {
      responsive: true,
      scales: { y: { beginAtZero: true } }
    }
  });

  new Chart(document.getElementById('monthlyChart'), {
    type: 'line',
    data: {
      labels: Object.keys(monthlyData),
      datasets: [{
        label: 'Monthly Sales',
        data: Object.values(monthlyData),
        borderColor: '#3b82f6',
        fill: false
      }]
    },
    options: { responsive: true }
  });

  new Chart(document.getElementById('topCustomersChart'), {
    type: 'doughnut',
    data: {
      labels: Object.keys(topCustomers),
      datasets: [{
        data: Object.values(topCustomers),
        backgroundColor: ['#34d399', '#60a5fa', '#fbbf24', '#f87171', '#c084fc']
      }]
    },
    options: { responsive: true }
  });

  document.querySelectorAll('.choices').forEach(function (el) {
    new Choices(el, {
      searchEnabled: true,
      itemSelectText: '',
    });
  });

  new Tablesort(document.getElementById('salesTable'));

  new List('salesList', {
    valueNames: ['name', 'customer', 'salesperson', 'total', 'status']
  });
});
